import torch, math
def deform(t, coef, T):
    k = torch.arange(1, coef.shape[-1] // 2 + 1, dtype=t.dtype)
    w = 2 * math.pi * k / T
    a, b = coef.chunk(2, dim=-1)
    return (a * torch.cos(w * t) + b * torch.sin(w * t)).sum(-1)

def drift(s, d):
    # s: 空间门控(s(xr)=0), d: 时间幅度
    return s * d  # 参考视图处 s=0 => 无修正

def reward(quality, acc, a_tgt):
    # 质量为主，未达加速目标时给惩罚
    return quality - 10.0 * max(0.0, a_tgt - acc)

import torch.nn as nn
class TermErrProxy(nn.Module):
    def __init__(self, dz, de=1, h=128):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(dz + de, h), nn.ReLU(), nn.Linear(h, 1))
    def forward(self, z_t, e_step):
        return self.net(torch.cat([z_t, e_step], dim=-1))

def eh_score(I, S, E, w=(1.0, 1.0, 1.0)):
    # I,S,E in {0,1} or rates; w: weights for Identify/Solve/Escalate
    a, b, c = w
    return (a * I + b * S + c * E) / (a + b + c)

def scaffold_strength(cap, lam0=1.0):
    # cap: estimated current capability in [0,1]
    return lam0 * max(0.0, 1.0 - cap)

def run(plan, exec_, g, s0, tmax=20):
    s, done = s0, False
    for _ in range(tmax):
        a = plan(g, s)          # 预测原子动作或终止
        if a is None:
            done = True
            break
        s = exec_(s, a)         # 生成视频片段，推进状态
    return s, done

def update_memory(M, obs, compress, B):
    M = compress(M, obs)   # 并入新观测并生成分层摘要
    return M[:B]           # 控制历史 token 成本有界
